Maye something saying that it is possible to define per user (and therefore per service) nftables rules on the *output* chain?

~~~nftables
#!/usr/sbin/nft -f

flush ruleset

table inet filter {

  chain httpd_output {
    ip daddr 127.0.0.1 tcp dport mysql accept comment "Allow access to MySQL";
    ip daddr 172.19.42.0/24 udp dport domain accept comment "Let PHP make DNS requests";
    ip daddr 172.19.42.0/24 tcp dport domain accept comment "Let PHP make DNS requests";
    ip daddr {127.0.0.1} tcp dport {submission, smtp} accept comment "Let PHP send emails";
    tcp sport {http, https} ct state {established,related} accept comment "Let Apache serve HTTP(S)";
    udp sport {https} ct state {established,related} accept comment "Let Apache serve HTTP(S)";
    reject;
  }

  chain output {
    type filter hook output priority filter;
    policy accept;
    skuid www-data jump httpd_output;
  } 

}
~~~

